"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[9470],{7007(e){e.exports=JSON.parse('{"title":"\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc774 \uc815\ub9d0 \ud544\uc694\ud55c\uac00\uc694?","date":"2024-10-25","coverUrl":null,"html":"<h2 data-notion-block-id=\\"125e548d-8a8e-80d6-8279-d170303bb1e8\\" id=\\"125e548d-8a8e-80d6-8279-d170303bb1e8\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc774 \uc815\ub9d0 \ud544\uc694\ud55c\uac00\uc694?</h2><a href=\\"https://www.coryetzkorn.com/blog/you-might-not-need-a-design-system\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.coryetzkorn.com/blog/you-might-not-need-a-design-system</a><a href=\\"https://truesparrow.com/blog/you-dont-need-a-design-system/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://truesparrow.com/blog/you-dont-need-a-design-system/</a><a href=\\"https://measured.co/blog/dont-build-a-design-system\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://measured.co/blog/dont-build-a-design-system</a><p data-notion-block-id=\\"9d32e5d4-4069-49d2-a3a4-ffb1f7812e48\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc740 \ub3c4\uc785\ud558\uba74 \ud3b8\ud574\uc9c0\ub294 \ub3c4\uad6c\uac00 \uc544\ub2c8\ub77c \uc0ac\ub0b4\uc5d0 \ud558\ub098\uc758 \uc81c\ud488\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc785\ub2c8\ub2e4. \uc81c\ud488\uc744 \ub9cc\ub4dc\ub294 \uc77c\uc778 \ub9cc\ud07c, \uac70\ub300\ud558\uace0 \ub2e4\ub8e8\uae30 \ud798\ub4e7\ub2c8\ub2e4. \uc704 \ub450 \uac1c\uc758 \uae00\uc740 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4dc\ub294 \ub300\uc2e0, \uc5ec\ub7ec\uac00\uc9c0 \ub300\uc548\uc744 \uc81c\uc2dc\ud569\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9 \uae00\uc740 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uacfc \uad00\ub828\ub41c \uc5ec\ub7ec\uac00\uc9c0 \uc815\uc758\ub97c \uba85\ud655\ud558\uac8c \ud558\uace0, \uc62c\ubc14\ub974\uac8c \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc744 \uc81c\uc2dc\ud569\ub2c8\ub2e4. \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc740 \uc774\ub978 \ucd94\uc0c1\ud654\uc77c \uc218\ub3c4 \uc788\uace0, \uad00\ub9ac \ud3ec\uc778\ud2b8\uc758 \ucd94\uac00\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc74c\uc744 \uba85\uc2ec\ud574\uc57c \ud569\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4, Shopify\uc5d0\uc11c\ub294 <a href=\\"https://medium.com/shopify-ux/design-systems-are-flawed-eecb60610efa\\">\ub514\uc790\uc778\uc2dc\uc2a4\ud15c\uc5d0 \ub300\ud55c \uc138 \uac00\uc9c0 \uc0ac\uc2e4\uacfc \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub904\uc57c \ud558\ub294\uc9c0</a>\ub97c \uc18c\uac1c\ud558\uace0, Github\uc5d0\uc11c\ub294 <a href=\\"https://youtu.be/Hx02SaL_IH0?si=8NLQMxW0b08X5rca\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \uad6c\ucd95 \ubc29\ubc95\uacfc \ud300\uc5d0 \ub530\ub77c \uc5b4\ub5bb\uac8c \uc811\uadfc\ud574\uc57c \ud558\ub294\uc9c0</a> \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1ba88554-0424-432b-b686-85befef9ac32\\" id=\\"1ba88554-0424-432b-b686-85befef9ac32\\">Web Components\uc758 \uc5ed\uc0ac</h2><a href=\\"https://www.baldurbjarnason.com/2024/liskovs-gun/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.baldurbjarnason.com/2024/liskovs-gun/</a><p data-notion-block-id=\\"0e05207a-b57a-4eb9-869b-b7d1a2be075e\\"><b>\uc2ec\uc724\uc12d</b>: <a href=\\"https://ones-to-watch.ethansup.net/news/post/b251305b-8c2f-4fcc-a159-c495533e1ac4#e6b4c895-1639-4fc6-9615-165f3a47cd82\\">Web Components\uc5d0 \ub300\ud55c \uc0dd\uac01\ub4e4</a>\uc5d0 \uc774\uc5b4\uc11c Web Components\uc758 \uc2dc\uc791\uacfc React \ubc29\uc2dd \uc124\uacc4\uc640\uc758 \ucda9\ub3cc, \uadf8\ub9ac\uace0 \uc6f9 \ud50c\ub7ab\ud3fc\uc758 \ubbf8\ub798\ub97c \ub9d0\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Web Components\ub97c \uc9d1\uc911\uc801\uc73c\ub85c \ub9d0\ud558\ub294 \uae00\uc774\uc9c0\ub9cc, React\uc758 \uc124\uacc4 \uae30\ubc18, \uadf8\ub85c \uc778\ud55c \ub2e8\uc810, \uc7ac\ubbf8\ub85c \ubcfc \uc218 \uc788\ub294 \uc5ed\uc0ac(Web Components\uc640 \ud568\uaed8)\ub97c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uae00\uc4f4\uc774\ub3c4 \ub9d0\ud558\ub4ef\uc774 Web Components\uc640 React\ub294 \uc7a5\ub2e8\uc810\uc774 \uc788\uc73c\uba70, \uc6f9 \ud45c\uc900\uacfc \uc6f9 \ud658\uacbd\uc740 \uc55e\uc73c\ub85c \ub098\uc544\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc678\uc5d0\ub3c4 <a href=\\"https://jjenzz.com/future-for-web-components-without-shadow-dom/\\">Shadow DOM\uc744 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 Web Components</a>\ub3c4 \uc18c\uac1c\ud558\uace0 \uc788\uc73c\ub2c8 Web Components\uc5d0 \ub300\ud574 \uad00\uc2ec\uc788\ub294 \ubd84\uc740 \ubcf4\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"d29ccd0e-2c07-46d1-aae1-7e9f69a5fe36\\" id=\\"d29ccd0e-2c07-46d1-aae1-7e9f69a5fe36\\">RSC \ub610\ud55c \\"\ud3ed\ud3ec \uc694\uccad \ubb38\uc81c\\"\uac00 \uc788\ub2e4.</h2><a href=\\"https://www.epicreact.dev/server-waterfall-problem-rscs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.epicreact.dev/server-waterfall-problem-rscs</a><p data-notion-block-id=\\"c3739271-4cab-4086-bbbd-1f623f855c74\\"><b>\uc2ec\uc724\uc12d</b>: \uae30\uc874 SSR\uc758 \ucd5c\uc0c1\ub2e8\uc5d0\uc11c \ub370\uc774\ud130 \ubc1b\uc544\uc624\uae30\uc5d0\uc11c RSC\uc758 \ucef4\ud3ec\ub10c\ud2b8\ub9c8\ub2e4 \ub370\uc774\ud130 \ubc1b\uc544\uc624\ub294 \ud615\uc2dd\uc73c\ub85c \ubcc0\uacbd \uc2dc\uc5d0 \uc11c\ubc84 \uc548\uc5d0\uc11c \uc694\uccad\uc744 \ud55c\ubc88\uc5d0 \ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \ubb38\uc81c\uac00 \uc788\uc2b5\ub2c8\ub2e4. RSC\ub97c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uace0 \uae00\uc5d0\uc11c \uc81c\uc2dc\ub41c Remix\uc758 loader \ud328\ud134\uc744 \uc0ac\uc6a9\ud558\uac70\ub098, <a href=\\"https://ones-to-watch.ethansup.net/news/post/11de548d-8a8e-80d0-9c96-f08026294b50#11de548d-8a8e-8080-b37e-db5e16bb4c14\\">Tanstack start\ucc98\ub7fc</a> \ud074\ub77c\uc774\uc5b8\ud2b8 \uc911\uc2ec \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \uc81c\uacf5\ud558\ub294 \ubc29\uc2dd\ub3c4 \uc788\uc73c\ub2c8 RSC\uc5d0\uc11c \ud601\uba85\uc801\uc778 \uae30\ub2a5\uc774 \ucd94\uac00\ub418\uc9c0 \uc54a\ub294 \uc774\uc0c1, \uc7a5\ub2e8\uc810\uc744 \uc870\uc728\ud574\uc57c\uaca0\ub124\uc694.</p><p data-notion-block-id=\\"3dbe4c90-3c7c-441f-9a80-4c3d927225bc\\"><b>\uae40\ub300\uad00</b>: \ucef4\ud3ec\ub10c\ud2b8 \ub9c8\ub2e4 \ub370\uc774\ud130\ub97c \ubc1b\uc544\uc624\ub294 \ud615\uc2dd\uc73c\ub85c \uc11c\ubc84 \uc548\uc5d0\uc11c \ub370\uc774\ud130\uc758 \uc694\uccad\uc758 \ud55c\ubc88\uc5d0 \uc774\ub8e8\uc5b4\uc9c0\uc9c0 \uc54a\uace0, waterfall \ud604\uc0c1\uc774 \ubc1c\uc0dd\ud574 \uc18d\ub3c4\uac00 \uc800\ud558\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uac8c \ub41c \uae00\uc774\uc5c8\uc2b5\ub2c8\ub2e4. SSR\uc758 \uc8fc\uc694 \uae30\ub2a5\uc778 NextJS\uc5d0\uc11c\ub294 \uc774\ub7f0 waterfall \ud604\uc0c1\ub4e4\uc744 \uc5c6\uc560\uae30 \uc704\ud574 <code>Promise.all</code>\uc744 \ud1b5\ud574 \uc694\uccad \ucc98\ub9ac\ub97c \ud558\uac70\ub098 <a href=\\"https://ones-to-watch.ethansup.net/news/post/abdeee1c-f704-449c-9b9c-77f2d5f1714a#e974e7a8-9bb8-45cd-afc3-502c83efca65\\">\ub80c\ub354\ub9c1 \uc804\ub7b5\uc5d0 \ub530\ub77c \ud574\uacb0</a>\ud558\ub294 \ubc29\ubc95\uc744 \uc0dd\uac01\ud574\uc57c \ud569\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"eccf0b72-16b2-4a28-9410-1c79962d41e9\\" id=\\"eccf0b72-16b2-4a28-9410-1c79962d41e9\\">React\uc640 dataset\uc73c\ub85c \uc7ac\ub80c\ub354\ub9c1 \ubc29\uc9c0\ud558\uae30</h2><a href=\\"https://www.nico.fyi/blog/tailwind-css-group-modifier-to-prevent-react-rerender\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nico.fyi/blog/tailwind-css-group-modifier-to-prevent-react-rerender</a><p data-notion-block-id=\\"4c7a1702-163a-495a-be92-6baf70c5a885\\">DOM\uc5d0 \uc9c1\uc811 \uc811\uadfc\ud558\uc5ec <code>dataset</code>\uc744 \uc124\uc815\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc2a4\ud0c0\uc77c\uc744 \ubc14\uafb8\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. <code>requestAnimationFrame()</code>\uc744 \uc0ac\uc6a9\ud558\uc5ec \ub80c\ub354\ub9c1 \ube14\ub77d\uc744 \ub9c9\uc740 \uac83\uc740 \ub208\uc5d0 \ub744\uc9c0\ub9cc, \uc124\uc815\ud55c \uc694\uc18c\uac00 \uc7ac\ub80c\ub354\ub9c1 \ub418\ub294 \uacbd\uc6b0 \ucd08\uae30\ud654\ub41c\ub2e4\ub294 \uc810\uacfc DOM\uc73c\ub85c \uc9c1\uc811 \uc811\uadfc\ud574 \uad00\ub9ac\uac00 \uc5b4\ub835\ub2e4\ub294 \uc810\uc740 \uace0\ub824\ud558\uace0 \uc0ac\uc6a9\ud574\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"125e548d-8a8e-80ec-bd8f-fc7c516e6059\\" id=\\"125e548d-8a8e-80ec-bd8f-fc7c516e6059\\">UI \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 \ubd84\ub958</h2><a href=\\"https://nerdy.dev/headless-boneless-and-skinless-ui\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nerdy.dev/headless-boneless-and-skinless-ui</a><p data-notion-block-id=\\"125e548d-8a8e-8031-9124-dd4a07f1553f\\">\uc5ec\ub7ec\uac00\uc9c0 UI \ud504\ub808\uc784\uc6cc\ud06c\uc640 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \ucd94\uc0c1\ud654\ud588\ub294\uc9c0\uc5d0 \ub530\ub77c \uc0c8\ub85c\uc6b4 \ub2e8\uc5b4\ub85c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1274f076-dd02-4bc2-801c-f1fce2d8ee1c\\" id=\\"1274f076-dd02-4bc2-801c-f1fce2d8ee1c\\">Safari \ud06c\ub85c\uc2a4 \ube0c\ub77c\uc6b0\uc9d5\uc758 \uc5ed\uc0ac</h2><a href=\\"https://webventures.rejh.nl/blog/2024/history-of-safari-show-stoppers/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webventures.rejh.nl/blog/2024/history-of-safari-show-stoppers/</a><p data-notion-block-id=\\"1b4c5cd8-b50c-469b-bb56-2f96f448154c\\">iOS\uc758 Webkit \uace0\uc815, \uadf8\ub9ac\uace0 \ub290\ub9b0 \ubc84\uadf8 \ub300\uc751, \uc77c\ubd80 \uc8fc\uc694 \uae30\ub2a5 \ubbf8\ub300\uc751\uc73c\ub85c \ud06c\ub85c\uc2a4 \ube0c\ub77c\uc6b0\uc9d5\uc774 \uc5b4\ub824\uc6e0\ub358 \uc5ed\uc0ac\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uba87 \uac00\uc9c0\uc758 \uae30\ub2a5\uc740 \uc544\uc9c1 \uace0\uccd0\uc9c0\uc9c0 \uc54a\uc558\ub2e4\uace0 \ud569\ub2c8\ub2e4. \uc8fc\uc758\ud574\uc11c \uc0ac\uc6a9\ud574\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"400109f7-e878-4d10-aedb-6793e275ac73\\" id=\\"400109f7-e878-4d10-aedb-6793e275ac73\\">\ud398\uc774\uc9c0 \uc885\ub8cc \ucef4\ud3ec\ub10c\ud2b8\uc5d0 <code>Esc</code>\ud0a4 \uc774\ubca4\ud2b8\ub97c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \uc774\uc720</h2><a href=\\"https://beeps.website/blog/2024-10-09-why-govuk-exit-this-page-doesnt-use-escape/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://beeps.website/blog/2024-10-09-why-govuk-exit-this-page-doesnt-use-escape/</a><p data-notion-block-id=\\"2ddfb43e-b5d2-4425-800c-ccc96f65b1df\\"><code>Esc</code>\ud0a4\ub97c \uc138 \ubc88 \ub204\ub974\ub294 \uc774\ubca4\ud2b8\ub97c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uace0 <code>Shift</code>\ud0a4\ub97c \uc0ac\uc6a9\ud55c \uc774\uc720\ub97c \uc801\uc740 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4. <code>Esc</code>\ub97c \uc0ac\uc6a9\ud560 \ub54c\uc758 \uc811\uadfc\uc131\uacfc \ub2e4\ub978 \ub2e8\ucd95\ud0a4\uc640 \uacb9\uce58\uc9c0 \uc54a\uc73c\ub824\ub294 \ub178\ub825\uc740 \uc0c1\uae30\ud560\ub9cc \ud558\ub124\uc694.</p><h2 data-notion-block-id=\\"8f8fb051-da41-42ec-9499-f52afc50dd12\\" id=\\"8f8fb051-da41-42ec-9499-f52afc50dd12\\">\uad6c\ud604\ud574\ubcf4\uae30</h2><a href=\\"https://www.joshuawootonn.com/react-drag-to-select\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshuawootonn.com/react-drag-to-select</a><a href=\\"https://www.nikhilsnayak.dev/blogs/the-true-nature-of-use-action-state\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nikhilsnayak.dev/blogs/the-true-nature-of-use-action-state</a><a href=\\"https://www.premieroctet.com/blog/en/notification-webview\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.premieroctet.com/blog/en/notification-webview</a><p data-notion-block-id=\\"125e548d-8a8e-8064-85ec-da036b821030\\">\uccab\ubc88\uc9f8 \uae00\uc740 Drag\ub85c \uc5ec\ub7ec DOM\uc744 \uc120\ud0dd\ud558\ub294 \ub85c\uc9c1\uc744 \uad6c\ud604\ud558\ub294 \ubc95\uc744 \uc18c\uac1c\ud55c \uae00\uc774\uace0, \ub450\ubc88\uc9f8 \uae00\uc740  \uae30\uc874\uc758 <code>useReducer</code>\ub97c \uc0ac\uc6a9\ud55c \uc811\uadfc\ubc95\uc5d0\uc11c <code>useActionState</code>\ub85c \ubcc0\uacbd\ud558\uba74\uc11c React 19\uc5d0\uc11c\uc758 Form \uc811\uadfc\ubc95\uc744 \uc54c\ub9ac\ub294 \uae00\uc785\ub2c8\ub2e4. \uc138\ubc88\uc9f8 \uae00\uc740 React Native \uc548 Webview\uc5d0\uc11c  \uc571 \uc54c\ub9bc \uad00\ub9ac\ud558\ub294 \uac00\uc774\ub4dc \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);